/* The native core's generators (kp_rng.h, ADR 0008) against vectors from executing the original 1.17.0.1 functions
 * (tests/golden/oracle, generated by tools/oracle/export_leaf_vectors.py). */
#include "kp_test.h"

#include <stdio.h>
#include <string.h>

#define TARGET "94dea44898a3934cdfae2a8149c0044db8ad1af4b4bc54306cdca3b1612d6ed0"

static const KpJson *golden(KpT *T, const char *name)
{
	char path[256];
	snprintf(path, sizeof path, "tests/golden/oracle/%s", name);
	return kp_t_golden(T, path);
}

static void game_raw_golden(KpT *T)
{
	const KpJson *g = golden(T, "rng_game.json"), *cases = kp_json_get(g, "cases");
	int k, n = 0;
	kp_t_eq_str(T, kp_json_field_str(g, "target_sha256", ""), TARGET, NULL);
	for (k = 0; k < kp_json_len(cases); k++) {
		const KpJson *c = kp_json_at(cases, k), *o = kp_json_get(c, "observed");
		uint32_t seed = (uint32_t)kp_json_field_int(c, "seed", 0), result;
		KpRngGame r;
		if (strcmp(kp_json_field_str(c, "kind", ""), "raw") != 0) continue;
		kp_rng_game_init(&r, 0);
		kp_rng_game_seed(&r, seed);
		kp_rng_game_set_enabled(&r, (uint32_t)kp_json_field_int(c, "enabled", 0));
		result = kp_rng_game_raw(&r, 0);
		kp_t_eq(T, result, kp_json_int(kp_json_at(o, 0), -1), "raw result seed %u", seed);
		kp_t_eq(T, r.state, kp_json_int(kp_json_at(o, 1), -1), "raw state seed %u", seed);
		kp_t_eq(T, r.total, kp_json_int(kp_json_at(o, 2), -1), "raw total seed %u", seed);
		kp_t_eq(T, r.counters[0], kp_json_int(kp_json_at(o, 3), -1), "raw counter seed %u", seed);
		n++;
	}
	kp_t_eq(T, n, 10, NULL);
}

static void game_range_golden(KpT *T)
{
	const KpJson *g = golden(T, "rng_game.json"), *cases = kp_json_get(g, "cases");
	int k, n = 0;
	for (k = 0; k < kp_json_len(cases); k++) {
		const KpJson *c = kp_json_at(cases, k), *o = kp_json_get(c, "observed"), *b = kp_json_get(c, "bounds");
		int64_t lo = kp_json_int(kp_json_at(b, 0), 0), hi = kp_json_int(kp_json_at(b, 1), 0);
		int64_t enabled = kp_json_field_int(c, "enabled", 0);
		uint32_t result;
		KpRngGame r;
		if (strcmp(kp_json_field_str(c, "kind", ""), "range") != 0) continue;
		kp_rng_game_init(&r, 0);
		kp_rng_game_seed(&r, 0xFFFFFFFFu);
		kp_rng_game_set_enabled(&r, (uint32_t)enabled);
		result = kp_rng_game_range(&r, 0, (uint32_t)lo, (uint32_t)hi);
		kp_t_eq(T, result, kp_json_int(kp_json_at(o, 0), -1), "range [%lld,%lld] enabled %lld", (long long)lo,
			(long long)hi, (long long)enabled);
		kp_t_eq(T, r.state, kp_json_int(kp_json_at(o, 1), -1), "range [%lld,%lld] enabled %lld", (long long)lo,
			(long long)hi, (long long)enabled);
		kp_t_eq(T, r.counters[0], kp_json_int(kp_json_at(o, 2), -1), "range [%lld,%lld] enabled %lld", (long long)lo,
			(long long)hi, (long long)enabled);
		n++;
	}
	kp_t_eq(T, n, 12, NULL);
}

static void game_flag_exchange_and_seed(KpT *T)
{
	KpRngGame r;
	kp_rng_game_init(&r, 77);
	kp_t_eq(T, kp_rng_game_set_enabled(&r, 1), 0, NULL);
	kp_t_eq(T, kp_rng_game_set_enabled(&r, 5), 1, NULL);
	kp_t_eq(T, r.initial_seed, 77, NULL);
	kp_rng_game_seed(&r, 1);
	kp_rng_game_raw(&r, 3);
	kp_rng_game_raw(&r, 3);
	kp_rng_game_raw(&r, 255);
	kp_t_eq(T, r.total, 3, NULL);
	kp_t_eq(T, r.counters[3], 2, NULL);
	kp_t_eq(T, r.counters[255], 1, NULL);
	kp_rng_game_seed(&r, 9);
	kp_t_eq(T, r.total, 0, NULL);
	kp_t_eq(T, r.counters[3], 0, NULL);
	kp_t_eq(T, r.state, 9, NULL);
	kp_t_eq(T, r.initial_seed, 77, NULL); /* the live seed is separate from the initial seed */
}

static void portrait_golden(KpT *T)
{
	const KpJson *g = golden(T, "rng_portrait.json"), *cases = kp_json_get(g, "cases");
	int k;
	kp_t_eq_str(T, kp_json_field_str(g, "target_sha256", ""), TARGET, NULL);
	kp_t_eq(T, kp_json_len(cases), 420, NULL);
	for (k = 0; k < kp_json_len(cases); k++) {
		const KpJson *c = kp_json_at(cases, k), *seed = kp_json_get(c, "seed"), *a = kp_json_get(c, "actual");
		KpRngPortrait p;
		int64_t v;
		p.x = (uint32_t)kp_json_int(kp_json_at(seed, 0), 0);
		p.y = (uint32_t)kp_json_int(kp_json_at(seed, 1), 0);
		p.z = (uint32_t)kp_json_int(kp_json_at(seed, 2), 0);
		v = kp_rng_portrait_draw(&p, kp_json_field_int(c, "low", 0), kp_json_field_int(c, "high", 0),
			(uint32_t)kp_json_field_int(c, "mask", 0));
		kp_t_eq(T, v, kp_json_int(kp_json_at(a, 0), -1), "portrait case %d", k + 1);
		kp_t_eq(T, p.x, kp_json_int(kp_json_at(a, 1), -1), "portrait case %d", k + 1);
		kp_t_eq(T, p.y, kp_json_int(kp_json_at(a, 2), -1), "portrait case %d", k + 1);
		kp_t_eq(T, p.z, kp_json_int(kp_json_at(a, 3), -1), "portrait case %d", k + 1);
	}
}

static void portrait_file_state(KpT *T)
{
	KpRngPortrait p;
	kp_rng_portrait_init(&p);
	kp_t_eq(T, p.x, 0x12345678, NULL);
	kp_t_eq(T, p.y, 0xe9e9e9e9u, NULL);
	kp_t_eq(T, p.z, 0x10934134, NULL);
}

/* MSVC rand: the documented sequence for the default seed 1. */
static void crt_sequence(KpT *T)
{
	static const uint32_t WANT[10] = { 41, 18467, 6334, 26500, 19169, 15724, 11478, 29358, 26962, 24464 };
	KpRngCrt c;
	int k;
	kp_rng_crt_init(&c, 1);
	for (k = 0; k < 10; k++) kp_t_eq(T, kp_rng_crt_rand(&c), WANT[k], "rand #%d", k + 1);
	kp_rng_crt_init(&c, 0xFFFFFFFFu);
	kp_t_eq(T, c.holdrand, 0xFFFFFFFFu, NULL);
	kp_rng_crt_rand(&c);
	kp_t_eq(T, c.holdrand, (4294967296LL - 214013 + 2531011) % 4294967296LL, NULL);
}

static void generators_are_independent(KpT *T)
{
	KpRngGame g;
	KpRngCrt c, c2;
	KpRngPortrait p;
	uint32_t gs, cs, ps;
	kp_rng_game_init(&g, 0);
	kp_rng_crt_init(&c, 1);
	kp_rng_portrait_init(&p);
	kp_rng_game_seed(&g, 123);
	kp_rng_game_set_enabled(&g, 1);
	gs = g.state;
	cs = c.holdrand;
	ps = p.x;
	kp_rng_crt_rand(&c);
	kp_rng_portrait_draw(&p, 0, 100, 128);
	kp_t_eq(T, g.state, gs, NULL);
	kp_rng_game_raw(&g, 0);
	kp_t_ok(T, c.holdrand != cs, NULL);
	kp_t_ok(T, p.x != ps, NULL);
	kp_rng_crt_init(&c2, 1);
	kp_rng_crt_rand(&c2);
	kp_t_eq(T, c.holdrand, c2.holdrand, NULL);
}

/* A snapshot is the generator's whole state: a copy continues as the original does. */
static void snapshot_continuation(KpT *T)
{
	KpRngGame g, g2;
	KpRngCrt c, c2;
	KpRngPortrait p, p2;
	int64_t a[500];
	int k;
	kp_rng_game_init(&g, 5);
	kp_rng_crt_init(&c, 9);
	kp_rng_portrait_init(&p);
	kp_rng_game_seed(&g, 0xDEADBEEFu);
	kp_rng_game_set_enabled(&g, 1);
	for (k = 1; k <= 1000; k++) {
		kp_rng_game_range(&g, (uint8_t)(k % 256), 0, (uint32_t)k);
		kp_rng_crt_rand(&c);
		kp_rng_portrait_draw(&p, 0, 2, 4);
	}
	g2 = g;
	c2 = c;
	p2 = p;
	for (k = 1; k <= 500; k++) {
		a[k - 1] = (int64_t)kp_rng_game_raw(&g, (uint8_t)(k % 7)) + kp_rng_crt_rand(&c) + kp_rng_portrait_draw(&p, 0, 100, 128);
	}
	for (k = 1; k <= 500; k++) {
		int64_t v = (int64_t)kp_rng_game_raw(&g2, (uint8_t)(k % 7)) + kp_rng_crt_rand(&c2)
			+ kp_rng_portrait_draw(&p2, 0, 100, 128);
		kp_t_eq(T, v, a[k - 1], "draw %d", k);
	}
	kp_t_eq(T, g2.total, g.total, NULL);
	kp_t_eq(T, g2.counters[3], g.counters[3], NULL);
}

static const KpTest TESTS[] = {
	{ "game_raw_golden", game_raw_golden, 0 },
	{ "game_range_golden", game_range_golden, 0 },
	{ "game_flag_exchange_and_seed", game_flag_exchange_and_seed, 0 },
	{ "portrait_golden", portrait_golden, 0 },
	{ "portrait_file_state", portrait_file_state, 0 },
	{ "crt_sequence", crt_sequence, 0 },
	{ "generators_are_independent", generators_are_independent, 0 },
	{ "snapshot_continuation", snapshot_continuation, 0 },
};
KP_SUITE(kp_suite_rng, "test_rng", TESTS);
